<?php $inventorySection='movements'; require dirname(__DIR__,2).'/components/admin/inventory-nav.php'; $labels=['initial'=>'Inicial','adjustment_in'=>'Ajuste +','adjustment_out'=>'Ajuste −','count_gain'=>'Conteo +','count_loss'=>'Conteo −','shrinkage'=>'Merma','correction_in'=>'Corrección +','correction_out'=>'Corrección −']; ?>
<div class="inventory-workspace inventory-history"><section class="admin-page-head"><div><p class="admin-kicker">MOVIMIENTOS</p><h1>Movimientos de inventario</h1><p>Consulta entradas, salidas y ajustes con su fecha, responsable y motivo.</p></div></section>
<form class="admin-panel admin-filter-bar admin-movement-filter" method="get" action="/admin/inventory/movements" data-admin-modal-get><?php if($variantId!==null):?><input type="hidden" name="variant_id" value="<?= e($variantId) ?>"><?php endif?><label class="admin-field"><span>Buscar</span><input type="search" name="q" maxlength="120" value="<?= e($q) ?>" placeholder="Producto, SKU o motivo"></label><label class="admin-field"><span>Sucursal</span><select name="branch_id"><?php if($allBranches??false):?><option value="">Todas las sucursales</option><?php endif?><?php foreach($branches as$b):?><option value="<?= e($b['id']) ?>" <?= $branchId===(int)$b['id']?'selected':'' ?>><?= e($b['name']) ?></option><?php endforeach?></select></label><label class="admin-field"><span>Tipo</span><select name="type"><option value="">Todos</option><?php foreach($types as$t):?><option value="<?= e($t) ?>" <?= $type===$t?'selected':'' ?>><?= e($labels[$t]??$t) ?></option><?php endforeach?></select></label><label class="admin-field"><span>Desde</span><input type="date" name="from" value="<?= e($from??'') ?>"></label><label class="admin-field"><span>Hasta</span><input type="date" name="until" value="<?= e($until??'') ?>"></label><button class="admin-secondary-button">Aplicar</button></form>
<section class="admin-panel admin-table-panel inventory-directory"><header class="inventory-directory-heading"><div><h2>Historial de movimientos</h2><p>Cada registro conserva la cantidad anterior y posterior.</p></div></header><?php if($page->items===[]):?><div class="inventory-empty"><h3>Sin movimientos para esta consulta</h3><p>Ajusta los filtros o revisa otra sucursal. Aquí aparecerán los movimientos cuando se registren.</p></div><?php else:?><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Fecha</th><th>Variante</th><th>Sucursal</th><th>Tipo</th><th>Cantidad</th><th>Antes → después</th><th>Responsable / motivo</th></tr></thead><tbody><?php foreach($page->items as$m):?><tr><td><?= e($m['created_at']) ?></td><td><div><strong><?= e($m['product_name']) ?></strong><small><?= e($m['sku'].' · '.$m['variant_name']) ?></small></div></td><td><?= e($m['branch_name']) ?></td><td><span class="admin-status"><?= e($labels[$m['movement_type']]??$m['movement_type']) ?></span></td><td><div><?= e($m['input_quantity'].' '.$m['input_symbol']) ?><small>Base: <?= e($m['base_quantity'].' '.$m['base_symbol']) ?></small></div></td><td><?= e($m['physical_before'].' → '.$m['physical_after']) ?></td><td><div><?= e($m['actor_name']) ?><small><?= e($m['reason']) ?></small></div></td></tr><?php endforeach?></tbody></table></div><?php endif?></section>

<?php if($page->offset>0||$page->hasMore):?><nav class="admin-pagination" aria-label="Páginas de movimientos"><?php foreach(['Anterior'=>max(0,$page->offset-25),'Siguiente'=>$page->offset+25] as $label=>$offset):?><?php if(($label==='Anterior'&&$page->offset>0)||($label==='Siguiente'&&$page->hasMore)):?><a data-admin-form-link href="/admin/inventory/movements?<?= e(http_build_query(['q'=>$q,'branch_id'=>$branchId,'variant_id'=>$variantId,'type'=>$type,'from'=>$from,'until'=>$until,'offset'=>$offset])) ?>"><?= e($label) ?></a><?php endif?><?php endforeach?></nav><?php endif?><div class="inventory-history-close"><a class="admin-secondary-button" data-admin-modal-cancel href="/admin/inventory">Volver a existencias</a></div></div>
